// Test the exact client runtime generated by the Rust source, without browser dependencies.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { runInNewContext } from 'node:vm';

const rust = readFileSync(new URL('../../src/web/reactivity.rs', import.meta.url), 'utf8');
const start = rust.indexOf('pub fn generate_client_runtime() -> String {');
assert.notEqual(start, -1, 'generate_client_runtime must be defined');
const match = rust.slice(start).match(/r#"([\s\S]*?)"#\s*\.to_string\(\)/);
const runtime = match ? match[1] : (() => {
  assert.match(rust, /include_str!\("client_runtime\.js"\)/, 'find emitted compiler-owned client runtime');
  return readFileSync(new URL('../../src/web/client_runtime.js', import.meta.url), 'utf8');
})();

function mount(values, readyState = 'complete') {
  const elements = values.map(([signal, content]) => ({
    dataset: { signal }, textContent: content,
  }));
  const listeners = new Map();
  const document = {
    readyState,
    querySelectorAll(selector) {
      if (selector === '[data-signal]') return elements;
      if (selector === '[data-action]') return [];
      throw new Error('unexpected selector: ' + selector);
    },
    addEventListener(name, listener) { listeners.set(name, listener); },
  };
  const window = {};
  runInNewContext(runtime, { window, document, console, URLSearchParams });
  return { elements, listeners, api: window.nulang };
}

for (const name of ['constructor', 'toString', '__proto__', 'hasOwnProperty']) {
  const { api, elements } = mount([[name, 'initial-' + name]]);
  assert.equal(api.signal(name).get(), 'initial-' + name, name + ': hydrate SSR value');
  api.signal(name).set('updated-' + name);
  assert.equal(api.signal(name).get(), 'updated-' + name, name + ': preserve signal state');
  assert.equal(elements[0].textContent, 'updated-' + name, name + ': update bound DOM');
}

{
  const { api, elements } = mount([
    ['count', '3'], ['count', '3'], ['constructor', 'safe'],
  ]);
  assert.equal(api.signal('count').get(), '3');
  api.signal('count').set('4');
  assert.deepEqual(elements.slice(0, 2).map(el => el.textContent), ['4', '4']);
  assert.equal(api.signal('constructor').get(), 'safe');
}

{
  const { api, listeners } = mount([['toString', 'deferred']], 'loading');
  assert.equal(api.signal('toString').get(), undefined, 'hydrate after DOM is ready');
  listeners.get('DOMContentLoaded')();
  assert.equal(api.signal('toString').get(), 'deferred');
}

console.log('web signal-name hydration regressions passed');
